-- Repaired form-template seed: 20260710054500_reseed_finance_legal_form_templates.
-- The original 2026-01 seed contained malformed JSON delimiters and is now a
-- safe historical marker. This idempotent seed preserves the intended forms.

with seed as (
  select
    (item->>'module')::public.module_type as module,
    item->>'name' as name,
    item->>'description' as description,
    item->'schema_json' as schema_json,
    coalesce((item->>'is_active')::boolean, true) as is_active
  from jsonb_array_elements($hpg_forms$[{"module":"finance","name":"Expense request","description":"Submit expense for reimbursement","schema_json":{"fields":[{"name":"expense_date","type":"date","label":"Expense Date","required":true},{"name":"amount","type":"number","label":"Amount ($)","required":true},{"name":"category","type":"select","label":"Category","options":["Travel","Supplies","Equipment","Services","Meals","Other"],"required":true},{"name":"description","type":"textarea","label":"Description","required":true},{"name":"receipt_attached","type":"checkbox","label":"Receipt Attached","required":true}]},"is_active":true},{"module":"finance","name":"Payment processing request","description":"Request payment processing for approved expenses or invoices","schema_json":{"fields":[{"name":"payee_name","type":"text","label":"Payee Name","required":true},{"name":"amount","type":"number","label":"Amount ($)","required":true},{"name":"payment_type","type":"select","label":"Payment Type","options":["Expense Reimbursement","Vendor Invoice","Grant Payment","Other"],"required":true},{"name":"due_date","type":"date","label":"Due Date"},{"name":"account_code","type":"text","label":"Account Code"},{"name":"approval_attached","type":"checkbox","label":"Approval Documentation Attached"}]},"is_active":true},{"module":"finance","name":"Budget adjustment request","description":"Request budget adjustment or transfer","schema_json":{"fields":[{"name":"from_account","type":"text","label":"From Account","required":true},{"name":"to_account","type":"text","label":"To Account","required":true},{"name":"amount","type":"number","label":"Amount ($)","required":true},{"name":"justification","type":"textarea","label":"Justification","required":true},{"name":"approval_required","type":"select","label":"Approval Level","options":["Department Head","VP","CEO"]}]},"is_active":true},{"module":"finance","name":"Receipt submission","description":"Submit receipt for expense reimbursement","schema_json":{"fields":[{"name":"expense_date","type":"date","label":"Expense Date","required":true},{"name":"vendor","type":"text","label":"Vendor","required":true},{"name":"amount","type":"number","label":"Amount ($)","required":true},{"name":"category","type":"select","label":"Category","options":["Travel","Supplies","Equipment","Services","Meals","Other"],"required":true},{"name":"description","type":"textarea","label":"Description"},{"name":"receipt_uploaded","type":"checkbox","label":"Receipt Uploaded","required":true}]},"is_active":true},{"module":"legal","name":"Contract review request","description":"Request legal review of contracts or agreements","schema_json":{"fields":[{"name":"contract_type","type":"select","label":"Contract Type","options":["Vendor Agreement","Partnership MOU","Grant Agreement","Lease","Employment","Other"],"required":true},{"name":"counterparty","type":"text","label":"Other Party Name","required":true},{"name":"value","type":"number","label":"Contract Value ($)"},{"name":"urgency","type":"select","label":"Urgency","options":["Low","Medium","High"],"required":true},{"name":"key_terms","type":"textarea","label":"Key Terms"},{"name":"notes","type":"textarea","label":"Additional Notes"}]},"is_active":true},{"module":"legal","name":"Compliance filing proof","description":"Submit evidence of regulatory filing completion","schema_json":{"fields":[{"name":"filing_type","type":"select","label":"Filing Type","options":["Annual Report","Tax Filing","State Registration","Federal Registration","Other"],"required":true},{"name":"filing_date","type":"date","label":"Filing Date","required":true},{"name":"jurisdiction","type":"text","label":"Jurisdiction","required":true},{"name":"confirmation_number","type":"text","label":"Confirmation/Reference Number"},{"name":"documentation_attached","type":"checkbox","label":"Documentation Attached","required":true},{"name":"next_due_date","type":"date","label":"Next Due Date"}]},"is_active":true}]$hpg_forms$::jsonb) as seeded(item)
)
insert into public.form_templates (module, name, description, schema_json, is_active)
select module, name, description, schema_json, is_active
from seed
on conflict (module, name) do update set
  description = excluded.description,
  schema_json = excluded.schema_json,
  is_active = excluded.is_active,
  updated_at = now();
